qs=[]
def mcq(n,topic,prompt,opts,answer,explain):
 qs.append(dict(id=f'a{n}',section='A',title=f'Soalan {n}',topic=topic,intro=prompt,fields=[dict(id=f'a{n}',type='choice',label='Pilih satu jawapan yang paling tepat.',options=opts,answer=answer,max=1,model=opts[answer]+'. '+explain)]))
