def match(id,label,opts,answer,model=None):return dict(id=id,type='select',label=label,options=opts,answer=answer,max=1,model=model or opts[answer])
dates=['27 Mei 1961','17 Januari 1962','1 September 1962','9 Julai 1963','16 September 1963']
qs.append(dict(id='b1',section='B',title='1. Langkah pembentukan Malaysia',topic='Pembentukan Malaysia',intro='Padankan setiap peristiwa dengan tarikh yang betul. Setiap padanan bernilai 1 markah. Pilih satu tarikh bagi setiap peristiwa.',fields=[match('b1a','(a) Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Singapura.',dates,0),match('b1b','(b) Suruhanjaya Cobbold ditubuhkan.',dates,1),match('b1c','(c) Referendum diadakan di Singapura.',dates,2),match('b1d','(d) Perjanjian Malaysia ditandatangani di London.',dates,3),match('b1e','(e) Malaysia dimasyhurkan.',dates,4)]))
qs.append(dict(id='b2',section='B',title='2. Gelaran dan lambang negeri',topic='Identiti dan asal usul negeri',intro='Lengkapkan maklumat negeri dengan memilih jawapan yang betul. Setiap jawapan bernilai 1 markah.',fields=[match('b2a','(a) Gelaran pemerintah negeri Johor.',['Raja','Sultan','Yang di-Pertua Negeri','Yang di-Pertuan Besar'],1),match('b2b','(b) Gelaran pemerintah Negeri Sembilan.',['Yang di-Pertuan Besar','Sultan','Raja','Yang di-Pertua Negeri'],0),match('b2c','(c) Gelaran ketua negeri Pulau Pinang.',['Sultan','Raja','Yang di-Pertua Negeri','Yang di-Pertuan Besar'],2),match('b2d','(d) Haiwan yang menjadi penyokong perisai pada jata negeri Melaka.',['Harimau','Pelanduk','Gajah','Burung kenyalang'],1),match('b2e','(e) Asal nama Pulau Pinang dikaitkan dengan sejenis pokok, iaitu...',['Pokok Melaka','Pokok getah','Pokok pinang','Pokok padi'],2)]))
places=['Masjid','Gereja','Kuil','Wat','Gurdwara']
qs.append(dict(id='b3',section='B',title='3. Agama dan rumah ibadat',topic='Masyarakat Malaysia',intro='Padankan agama dengan rumah ibadat yang sesuai. Untuk agama Buddha dalam set padanan ini, gunakan wat. Setiap padanan bernilai 1 markah.',fields=[match('b3a','(a) Islam',places,0),match('b3b','(b) Kristian',places,1),match('b3c','(c) Hindu',places,2),match('b3d','(d) Buddha',places,3,'Wat. Tokong dan vihara juga merupakan rumah ibadat sesetengah penganut Buddha; wat ialah pilihan yang disediakan dalam padanan ini.'),match('b3e','(e) Sikh',places,4)]))
qs.append(dict(id='b4',section='B',title='4. Ekonomi, sukan dan hubungan luar',topic='Pembangunan dan hubungan antarabangsa',intro='Pilih jawapan yang betul bagi setiap pernyataan. Setiap jawapan bernilai 1 markah.',fields=[match('b4a','(a) Sebelum merdeka, ramai buruh India yang tinggal di ladang terlibat dalam kegiatan...',['Perladangan getah','Pembuatan kapal terbang','Pembuatan cip komputer','Pembuatan satelit'],0,'Perladangan getah. Ini konteks sejarah sebahagian masyarakat di kawasan ladang, bukan pekerjaan semua orang India.'),match('b4b','(b) Malaysia menjadi tuan rumah Sukan Komanwel di Kuala Lumpur pada tahun...',['1957','1963','1985','1998'],3),match('b4c','(c) Datuk Lee Chong Wei ialah tokoh sukan...',['Skuasy','Terjun','Badminton','Bola sepak'],2),match('b4d','(d) OIC merujuk kepada pertubuhan...',['Pertubuhan Kerjasama Islam','Persatuan Negara-negara Asia Tenggara','Pertubuhan Bangsa-Bangsa Bersatu','Komanwel'],0),match('b4e','(e) Antara matlamat OIC ialah...',['Menamatkan semua hubungan diplomatik','Mengeratkan perpaduan dan kerjasama negara anggota','Menghapuskan budaya semua negara anggota','Melarang kerjasama pendidikan'],1)]))
def written(id,label,max,model,criteria=None,concepts=None):
 f=dict(id=id,type='text',label=label,max=max,model=model)
 if criteria:f['rules']=criteria
 if concepts:f['concepts']=concepts
 return f
qs.append(dict(id='c1',section='C',title='1. Perayaan dan perpaduan masyarakat',topic='Masyarakat Malaysia',intro='Sekolah Kebangsaan Harmoni akan mengadakan sambutan perayaan yang melibatkan murid pelbagai kaum. Setiap kumpulan akan memperkenalkan makanan, pakaian dan kesenian tradisional. Jawab menggunakan ayat sendiri.',fields=[written('c1a','(a) Nyatakan dua kepentingan sambutan perayaan pelbagai kaum di Malaysia.',2,'Mana-mana dua isi berbeza, 1 markah setiap isi: mengeratkan perpaduan / hubungan masyarakat; memupuk sikap hormat atau toleransi; mengenali adat dan budaya kaum lain; memelihara warisan budaya. Isi yang sama diulang tidak mendapat markah tambahan.',concepts=[['perpaduan','silaturahim','hubungan','muhibah','muhibbah'],['hormat','toleransi'],['mengenali','memahami','pengetahuan','mempelajari'],['warisan','memelihara budaya','mengekalkan budaya']]),written('c1b','(b) Cadangkan satu aktiviti yang boleh dijalankan semasa sambutan itu. Jelaskan bagaimana aktiviti tersebut melibatkan murid pelbagai kaum dan kesannya terhadap perpaduan.',3,'Contoh: Mengadakan persembahan tarian tradisional secara berkumpulan (1). Murid pelbagai kaum berlatih dan bekerjasama dalam satu kumpulan (1), lalu lebih memahami budaya rakan dan mengeratkan hubungan (1). Terima aktiviti lain yang sesuai dengan penjelasan dan kesan yang sepadan. Pecahan: aktiviti 1 + penglibatan bersama 1 + kesan 1.',criteria=[[['tarian','persembahan','pameran','jamuan','rumah terbuka','kuiz','permainan','bengkel','masakan','pakaian']],[['bersama','bekerjasama','pelbagai kaum','campuran','semua kaum']],[['perpaduan','hubungan','memahami','hormat','silaturahim','muhibah','muhibbah']]])]))
qs.append(dict(id='c2',section='C',title='2. Sukan mengharumkan nama negara',topic='Pembangunan negara',intro='Malaysia pernah menjadi tuan rumah Sukan Komanwel pada tahun 1998. Atlet seperti Nicol David dan Lee Chong Wei pula mengharumkan nama negara melalui pencapaian sukan mereka.',fields=[written('c2a','(a) Nyatakan dua faedah penganjuran sukan antarabangsa kepada Malaysia.',2,'Mana-mana dua isi berbeza, 1 markah setiap isi: meningkatkan pendapatan negara / peniaga; menarik pelancong; memperkenalkan / menaikkan imej negara; menyediakan atau menaik taraf kemudahan sukan; mewujudkan peluang pekerjaan; mengeratkan perpaduan atau hubungan antarabangsa. Terima isi munasabah yang berkaitan.',concepts=[['pendapatan','ekonomi','jualan','perniagaan'],['pelancong','pelancongan'],['imej','terkenal','nama negara','memperkenalkan negara'],['kemudahan','infrastruktur','stadium'],['pekerjaan','peluang kerja'],['perpaduan','hubungan']]),written('c2b','(b) Sebagai murid, cadangkan satu tindakan untuk menghargai jasa atlet negara. Jelaskan cara melakukannya dan satu kesan positif tindakan itu.',3,'Contoh: Menghasilkan buku skrap tentang atlet negara (1). Mencatat dan berkongsi kisah latihan serta pencapaian mereka dengan rakan (1), supaya murid menghargai usaha atlet dan mencontohi sikap gigih (1). Terima contoh lain seperti memberi sokongan berhemah: menyokong atlet (1), memberi kata semangat tanpa menghina ketika kalah (1), meningkatkan motivasi / semangat atlet (1). Pecahan: tindakan 1 + pelaksanaan 1 + kesan 1.',criteria=[[['buku skrap','poster','sokong','sokongan','penghargaan','mencontohi','menghargai','pameran']],[['berkongsi','mencatat','kata semangat','tidak menghina','tanpa menghina','membaca','menulis','mempelajari','menceritakan']],[['gigih','motivasi','semangat','bangga','menghargai','inspirasi','disiplin','cinta negara']]])]))
assert len(qs)==26
assert sum(f['max'] for q in qs for f in q['fields'])==50
assert [sum(f['max'] for q in qs if q['section']==s for f in q['fields']) for s in 'ABC']==[20,20,10]
(root/'dist/questions-sejarah.js').write_text('const QUESTIONS = '+json.dumps(qs,ensure_ascii=False)+';\n')
